<body ontouchstart>
	<div id="player">
		<video-js id="video" class="vjs-default-skin vjs-big-play-centered" controls loop playsinline muted preload="auto" crossorigin="anonymous"></video-js>
		<div class="play-video"><div><img src="play.svg"></div></div>
	</div>
	<div id="three"></div>
	<img id="vignette" src="vignette.png"/>
	<div id="count">
		<div class="download"></div>
		<div class="remaining"></div>
	</div>
	<div id="button">
		<audio id="music">
			<source type="audio/mpeg">
		</audio>
		<div>
			<a id="sound" title="聆聽" href="javascript:playSound();">
				<div><img src="icon/volume_up.png"></div>
			</a>
			<a id="email" title="電子郵件" target="_blank">
				<div><img src="icon/email.png"></div>
			</a>
			<a id="phone" title="電話" target="_blank">
				<div><img src="icon/call.png"></div>
			</a>
			<a id="telegram" title="Telegram" target="_blank">
				<div><img src="icon/telegram.png"></div>
			</a>
			<a id="whatsapp" title="WhatsApp" target="_blank">
				<div><img src="icon/whatsapp.png"></div>
			</a>
			<a id="line" title="LINE" target="_blank">
				<div><img src="icon/line.png"></div>
			</a>
			<a id="wechat" title="微信" target="_blank">
				<div><img src="icon/wechat.png"></div>
			</a>
			<a id="facebook" title="Facebook" target="_blank">
				<div><img src="icon/facebook.png"></div>
			</a>
			<a id="instagram" title="Instagram" target="_blank">
				<div><img src="icon/instagram.png"></div>
			</a>
			<a id="twitter" title="X" target="_blank">
				<div><img src="icon/x.png"></div>
			</a>
			<a id="youtube" title="YouTube" target="_blank">
				<div><img src="icon/youtube.png"></div>
			</a>
			<a id="tiktok" title="TikTok" target="_blank">
				<div><img src="icon/tiktok.png"></div>
			</a>
			<a id="douyin" title="抖音" target="_blank">
				<div><img src="icon/tiktok.png"></div>
			</a>
			<a id="web" title="網站" target="_blank">
				<div><img src="icon/web.png"></div>
			</a>
			<a id="qrcode" title="QR Code" href="javascript:$('#qrcode-panel')[0].open();">
				<div><img src="icon/qrcode.png"></div>
			</a>
			<a id="contact" title="新增至通訊錄" href="javascript:addContacts();">
				<div>
					<div class="contact">
						<img src="icon/contact.png">
						<div class="line top"></div>
						<div class="line"></div>
						<div class="line bottom"></div>
					</div>
					<div class="add">
						<div></div>
						<div class="horizontal"></div>
					</div>
				</div>
			</a>
		</div>
	</div>
	<div id="alert-window">
		<div class="close"><img src="icon/close.png"></div>
		<div class="title"></div>
		<button data-confirm></button>
	</div>
	<div id="qrcode-panel">
		<div>
			<div class="qrcode"></div>
			<div class="close"><img src="icon/close.png"></div>
		</div>
	</div>
	<div id="powered"><a href="https://www.lightmatrix3d.com/" target="_blank">Powered by Light Matrix Inc. <span>光陣三維</span></a></div>
	<a href="https://www.lightmatrix3d.com/" target="_blank">
		<div id="logo">
			<div>光陣三維</div>
			<div class="english">LightMatrix</div>
		</div>
	</a>
	<div id="start-page">
		<div id="loading" class="rotate"></div>
		<div id="info"></div>
	</div>
	<div id="log"></div>
</body>

</html>